solution.solution.cpp:
class Player
{
public:
    enum class State { idle, running, jumping };

    State state() const { return m_state; }
    void run() { m_state = State::running; }
    void jump() { if (m_state == State::running) m_state = State::jumping; }
    void stop() { m_state = State::idle; }

private:
    State m_state{ State::idle };
};

unitTests:
TEST("starts idle") { const Player p{}; CHECK(p.state() == Player::State::idle); }
TEST("run then jump") { Player p{}; p.run(); CHECK(p.state() == Player::State::running); p.jump(); CHECK(p.state() == Player::State::jumping); }
TEST("cannot jump from idle") { Player p{}; p.jump(); CHECK(p.state() == Player::State::idle); }
TEST("stop") { Player p{}; p.run(); p.jump(); p.stop(); CHECK(p.state() == Player::State::idle); }

